import{_ as r,a0 as l,w as p,s as d,ao as a,I as t,a1 as n,A as o,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 中创建一个共享目录 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中创建一个共享目录 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中创建一个共享目录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中创建一个共享目录 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170201 How to Create a Shared Directory for All Users in Linux","title":"如何在 Linux 中创建一个共享目录","tag":"201702","desc":""},"relativePath":"201702/20170201 How to Create a Shared Directory for All Users in Linux.md","filePath":"[post].md"}'),u={name:"201702/20170201 How to Create a Shared Directory for All Users in Linux.md"};function g(h,s,m,k,c,w){const e=l("Link");return p(),d("div",null,[s[17]||(s[17]=a(`<h1 id="如何在-linux-中创建一个共享目录" tabindex="-1">如何在 Linux 中创建一个共享目录 <a class="header-anchor" href="#如何在-linux-中创建一个共享目录" aria-label="Permalink to “如何在 Linux 中创建一个共享目录”">​</a></h1><p>作为系统管理员，你可能有一个特定目录，你希望为 Linux 服务器上的每个用户授予读/写访问权限。在本指南中，我们将回顾如何在 Linux 中对特定目录（共享目录）上的所有用户启用写访问。</p><p>这要求设置适当的访问权限，而最有效、可靠的方法是为所有要共享或对特定目录的写访问权的用户分配一个公共组。</p><p>如果你系统中还没有存在这个目录和公众组，用下面的命令创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /var/www/reports/</span></span>
<span class="line"><span>$ sudo groupadd project</span></span></code></pre></div><p>接着将对目录 <code>/var/www/reports/</code> 有写权限的用户添加到 <code>project</code> 组中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G project tecmint</span></span></code></pre></div>`,7)),t("p",null,[n(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/01/Create-Common-Directory-Group.png"},{default:o(()=>[...s[0]||(s[0]=[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/01/Create-Common-Directory-Group.png",alt:"Create Common Directory Group"},null,-1)])]),_:1})]),s[18]||(s[18]=a(`<p><em>创建公共目录组</em></p><p>上面命令使用到的标志和参数是：</p><ol><li><code>-a</code> – 将用户添加到增补组中。</li><li><code>-G</code> – 指定组名。</li><li><code>project</code> – 组名。</li><li><code>tecmint</code> – 已有的用户名。</li></ol><p>在这之后，给目录配置适当的权限，<code>-R</code> 会让操作递归进入子目录中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chgrp -R project /var/www/reports/</span></span>
<span class="line"><span>$ sudo chmod -R 2775 /var/www/reports/</span></span></code></pre></div><p>解释下上面 <code>chmod</code> 命令中的 <code>2775</code>：</p><ol><li><code>2</code> - 打开 setGID 位，意味着新创建的子文件继承与目录相同的组，新创建的子目录继承父目录的 setGID 位。</li><li><code>7</code> - 为所有者提供 rwx 权限。</li><li><code>7</code> - 给组 rwx 权限。</li><li><code>5</code> - 为其他人提供 rx 权限。</li></ol><p>你可以使用下面的命令创建更多的系统用户并将它们添加到目录组中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd -m -c &quot;Aaron Kili&quot; -s/bin/bash -G project aaronkilik</span></span>
<span class="line"><span>$ sudo useradd -m -c &quot;John Doo&quot; -s/bin/bash -G project john</span></span>
<span class="line"><span>$ sudo useradd -m -c &quot;Ravi Saive&quot; -s/bin/bash -G project ravi</span></span></code></pre></div><p>接着创建每个用户存储他们项目报告的子目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /var/www/reports/aaronkilik_reports</span></span>
<span class="line"><span>$ sudo mkdir -p /var/www/reports/johndoo_reports</span></span>
<span class="line"><span>$ sudo mkdir -p /var/www/reports/ravi_reports</span></span></code></pre></div><p>现在你可以创建文件/文件，并分享给该组的其他用户了。</p>`,12)),t("p",null,[s[2]||(s[2]=i("就是这样了！在本篇中，我们回顾了如何启用所有用户对特定目录的写权限。要了解更多关于 Linux 中的用户/组，阅读",-1)),n(e,{href:"http://www.tecmint.com/manage-users-and-groups-in-linux/"},{default:o(()=>[...s[1]||(s[1]=[i("如何管理用户/组和属性",-1)])]),_:1}),s[3]||(s[3]=i("。",-1))]),s[19]||(s[19]=t("p",null,"记得在评论栏中留下你对这篇文章的想法。",-1)),s[20]||(s[20]=t("hr",null,null,-1)),s[21]||(s[21]=t("p",null,"译者简介：",-1)),s[22]||(s[22]=t("p",null,"Aaron Kili 是 Linux 和 F.O.S.S 爱好者，将来的 Linux SysAdmin 和 web 开发人员，目前是 TecMint 的内容创建者，他喜欢用电脑工作，并坚信分享知识。",-1)),s[23]||(s[23]=t("hr",null,null,-1)),t("p",null,[s[5]||(s[5]=i("via: ",-1)),n(e,{href:"http://www.tecmint.com/create-a-shared-directory-in-linux/"},{default:o(()=>[...s[4]||(s[4]=[i("http://www.tecmint.com/create-a-shared-directory-in-linux/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=i("作者：",-1)),n(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:o(()=>[...s[6]||(s[6]=[i("Aaron Kili",-1)])]),_:1}),s[10]||(s[10]=i(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[7]||(s[7]=[i("geekpi",-1)])]),_:1}),s[11]||(s[11]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[12]||(s[12]=[i("LCTT",-1)])]),_:1}),s[15]||(s[15]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[13]||(s[13]=[i("Linux中国",-1)])]),_:1}),s[16]||(s[16]=i(" 荣誉推出",-1))])])}const C=r(u,[["render",g]]);export{x as __pageData,C as default};
